-- 修复「带显式 id 搬行后自增序列落后」导致的主键冲突
-- （典型症状：duplicate key value violates unique constraint "token_usage_pkey"，Key (id)=(N) already exists）。
--
-- 背景：旧库导入与 SQLite → PostgreSQL 行复制都用显式 id 插入。GENERATED BY DEFAULT 允许显式值，
-- 但不会推进底层序列，于是应用下一次自增插入会撞上已经搬过去的行。运行期的搬行已由
-- SqliteToTargetCopier → IdentitySequenceSync 就地拨正；本迁移负责一次性修好已被写坏的库。
--
-- 幂等：已经对齐的库再执行一遍结果不变（setval 到 MAX + 1，is_called=false）。
DO $$
DECLARE
    item record;
    sequence_name text;
BEGIN
    FOR item IN
        SELECT c.relname AS table_name, a.attname AS column_name
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        JOIN pg_attribute a ON a.attrelid = c.oid
        WHERE n.nspname = current_schema()
          AND c.relkind = 'r'
          AND a.attnum > 0
          AND NOT a.attisdropped
          AND pg_get_serial_sequence(format('%I.%I', n.nspname, c.relname), a.attname) IS NOT NULL
    LOOP
        sequence_name := pg_get_serial_sequence(
            format('%I.%I', current_schema(), item.table_name), item.column_name);
        EXECUTE format(
            'SELECT setval(%L::regclass, COALESCE((SELECT MAX(%I) FROM %I), 0) + 1, false)',
            sequence_name, item.column_name, item.table_name);
    END LOOP;
END $$;
